\begin{tikzpicture}[x=8mm,y=8mm,font=\fontsize{10}{12}\selectfont]
\definecolor{gridcolour}{HTML}{CCCCCC}
\draw[step=4mm,gridcolour] (-3,-3) grid (3,3);
\draw[<->,black] (-3.3,0)--(3.3,0);
\draw[<->,black] (0,-3.3)--(0,3.3);
\path (3.3,0) node[right] {$x$} (0,3.3) node[above] {$y$};
\foreach \v in {-3,-2,-1,1,2,3} {\draw[black] (\v,-0.06)--(\v,0.06);\draw[black] (-0.06,\v)--(0.06,\v);\path (\v,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\v$};\path (0,\v) node[left,font=\fontsize{8.5}{10}\selectfont] {$\v$};}
\fill[black] (-2,1) circle (1.5pt) (1.5,-2) circle (1.5pt) (-1,-2) circle (1.5pt);
\path (-2,1) node[above left] {$A$} (1.5,-2) node[below right] {$B$} (-1,-2) node[below left] {$C$};
